CREATE TABLE IF NOT EXISTS qps_question_bank_drafts (
id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, staff_code VARCHAR(100) NOT NULL, dept_code VARCHAR(50) NULL, dept_name VARCHAR(255) NULL, paper_code VARCHAR(100) NOT NULL, course_title VARCHAR(255) NULL, semester VARCHAR(50) NOT NULL, academic_year VARCHAR(20) NOT NULL, exam_type VARCHAR(120) NOT NULL, regulation VARCHAR(80) NULL, degree_level VARCHAR(30) NULL, max_marks INT NOT NULL DEFAULT 75, total_questions INT NOT NULL DEFAULT 0, status ENUM('DRAFT','SUBMITTED_TO_HOD','REJECTED') NOT NULL DEFAULT 'DRAFT', source_format VARCHAR(20) NULL, source_file_name VARCHAR(255) NULL, source_path VARCHAR(700) NULL, archive_path VARCHAR(700) NULL, questions_json LONGTEXT NOT NULL, qbb_id BIGINT UNSIGNED NULL, qbb_checked TINYINT(1) NOT NULL DEFAULT 0, qbb_check_result_json LONGTEXT NULL, qbb_checked_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, submitted_at DATETIME NULL, hod_reviewed_by VARCHAR(100) NULL, hod_reviewed_at DATETIME NULL, review_comments TEXT NULL, PRIMARY KEY(id), KEY idx_course(paper_code,semester,academic_year), KEY idx_staff(staff_code), KEY idx_status(status), KEY idx_qbb(qbb_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
